import sys

# Function to build tree and initialize distances for LCA
def build_tree(parent_list):
    tree = [{}]
    stage = 1
    for i, parent in enumerate(parent_list, start=2):
        if parent not in tree[stage]:
            tree[stage][parent] = stage
        tree[stage][i] = tree[stage][-1]
        stage += 1
    return tree

# Function to get LCA using the distances array
def find_LCA(parent, child1, child2):
    reps = 1
    while True:
        reps += 1
        if abs(parent[child1] - parent[child2]) < reps:
            return reps
        child1 = parent[child1]
        child2 = parent[child2]

# Function to process queries
def process_queries(tree, queries):
    for query in queries:
        if query[0] == 1:
            l, r, x = query[1], query[2], query[3]
            for i in range(l - 1, r):
                tree[l][i] = max(tree[l][i] - x, 1)
        else:
            u, v = query[1], query[2]
            parent_u, parent_v = tree[1][u], tree[1][v]
            return find_LCA(parent_u, parent_v, 1) - 1
    return None

# Main function
def main():
    n, q = map(int, sys.stdin.readline().strip().split())
    parent_list = list(map(int, sys.stdin.readline().strip().split()))
    tree = build_tree(parent_list)
    queries = []
    for _ in range(q):
        query_type, *values = map(int, sys.stdin.readline().strip().split())
        queries.append((query_type, *values))
    result = process_queries(tree, queries)
    if result is not None:
        print(result)
    else:
        print('queries max value exceeded')

if __name__ == "__main__":
    main()
