import math

class SantaSanta:
    def __init__(self, n, g, b, x, y, presents):
        self.n = n
        self.g = g
        self.b = b
        self.x = x
        self.y = y
        self.presents = presents
        self.visited = []
        self.reimedes = []
        self.bag = []

    def execute(self, command, data):
        if command == 0:
            return f"0"
        elif command == 1:
            self.reimedes.append(f"1 {self.x} {self.y}")
        elif command == 2:
            self.bag.append(data)
        elif command == 3:
            self.bag.remove(data)
        elif command == 4:
            self.reimedes.append(f"2 {self.g//self.b*1}")
        else:
            raise ValueError(f"Invalid command: {command}")

    def get_score(self):
        return len(self.reimedes)

def solve(N, G, B, X, Y, presents):
    s = SantaSanta(N, G, B, X, Y, presents)
    total_distance = 0
    while s.visited != [s.g // B]:
        min_presentation = None
        min_presentation_distance = math.inf
        for i in range(s.g):
            if i in s.visited:
                continue
            distance = abs(s.x - s.presents[i] + i) + abs(s.y - s.presents[i] + i) * 2
            value = s.bag.count(i)
            if value * i < min_presentation_distance:
                min_presentation_distance = value * i
                min_presentation = i
        if min_presentation:
            total_distance += min_presentation_distance
            s.reimedes.append(f"2 {min_presentation}")
            s.visited.append(min_presentation)
        else:
            s.reimedes.append("1")
            return total_distance

