from collections import deque

def can_reach_port(board, starts, days, wind_info):
    # Function to determine if the ship can reach the port in the given number of days
    def bfs(days, start):
        directions = {'N': (-1, 0), 'S': (+1, 0), 'E': (0, +1), 'W': (0, -1)}
        q = deque([start])
        visited = set([start])
        current_days = 0
        max_days_to_port = 0

        while q and current_days <= days:
            for _ in range(len(q)):
                x, y = q.popleft()
                if board[x][y] == 'P':
                    max_days_to_port = days + current_days
                    return True
                for dx, dy in directions.values():
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(board) and 0 <= ny < len(board[0]) and (nx, ny) not in visited:
                        new_d = board[nx][ny] == 'M'
                        visited.add((nx, ny))
                        if board[nx][ny] == 'P' or (new_d and board[nx][ny] >= 0):
