def optimalOrdering(opponent: List[int], team: List[int]) -> str:
    """
    Determines if it's possible for the team to win the match and returns the optimal order.
    If possible, returns the lexicographically smallest order as a string.
    """
    opponent.sort()
    team.sort()
    if len(team) == 1 and team[0] > opponent[0]:
