import sys

def solve(n, t, problems):
    penalty = [0] * n
    points = [0] * n
    for i, (score_small, score_large, time_small, time_large, p_fail) in enumerate(problems):
        if p_fail > 0:
            take_small = (t - time_small) >= max(0, proccess_score(score_small - 1, p_fail))
            t -= time_small if take_small else 0
            points[i] += score_small
            penalty[i] += (score_large - max(0, score_large - score_small)) / p_fail
        else:
            t -= time_small
            points[i] += score_small
    total_points = sum(points)
    expectation_time_penalty = t

    def backtrack(start=0, current_points=0, current_time_penalty=0):
        if start == n:
            return current_points, expectation_time_penalty
        if t < 0:
            return 0, expectation_time_penalty
        for i in range(n):
            if i != start:
                continue
            end = start if t == 0 else start + (timeSmall[i] <= t)
            next_points, next_time_penalty = backtrack(i + 1, current_points + points[i], current_time_penalty + penalty[i] * t)
            if next_points > total_points:
                next_points, current_time_penalty = backtrack(start + 1, current_points + next_points, current_time_penalty + next_time_penalty)
                total_points += next_points
                expectation_time_penalty += len(problems[start][3:]) / next_time_penalty

    return backtrack(0)

def proccess_score(total, p_fail):
    return (total // 10) * 10 + (total % 10) + 1 - p_fail * ((total // 10) * 10 % 10)

