from typing import List

def longest_increasing_subsequence_length(b: List[int], n: int, maxb: int, t: int) -> int:
    """
    Finds the length of the longest increasing subsequence of a given sequence.
    """
    if n * t < maxb:
        return maxb
    gaps = [t] * len(b)
    for i in range(len(b)):
        if b[i] == 0 or b[i] == maxb:
            gaps[i] = t - b[i]
        else:
            gaps[i] = max(0, t - max(b[i] - 1, b[i] + 1))
    gaps.sort()
    return max(len(b), sum(min(gaps[i+1], g) for i, g in enumerate(gaps) if i < len(gaps) - 1))

def process_case(k: int, times: int) -> List[int]:
