    if S < 4:
        return 0
    r = S // 3
    if S % 3 != 0:
        return 0
    if S == 3:
        return 9

    mod_sum = 0  # Cumulative sum modulo MOD
    res = 0
    counter = 0

    for i in range(1, r + 2):
        mod_sum = (10 * mod_sum + i) % MOD  # Modulo arithmetic
        mod_sum = (self.lmbda(mod_sum) + mod_sum) % MOD  # Add the result of self.lmbda(mod_sum)
        if counter < 9:
            mod_sum += 1  # Add the last item
        mod_sum += mod_sum // counter  # Dividing by counter modulo MOD
        res = (res + mod_sum) % MOD  # Add result of mod_sum plus res

        counter += 1

    return res

def lmbda_sum(array):
    lmbda = 0
    for a in array:
        lmbda = (10 * lmbda + a) % MOD
    return lmbda

