from math import log10

def nth_digit_sum(n):
    """Sums the first n numbers in number 1, followed by ones: 1+2+3+...+n."""
    return sum(map(int, str(sum(range(1, n+1)))))

MOD = 10**9 + 7

def count_sequences(S):
    """Counts the number of sequences of (l, r) where f(l) + ... + f(r) = S."""

    def within_range(x1, x2):
        """Checks whether x1 <= x2 < x1*10 from the least significant digit."""
        total_digits = x1 + 1
        n = 1
        while n <= total_digits:
            if x2 >= n**2:
                break
            x2 += x1 * 10 ** (n-1)  # Advance to the next more significant digit for the next (l, r)
            n += n  # Increase by twice the current digit length

        return x2 < x1 * 10

    def limit_by_odd_m (m):
        """Lower bound given odd limit m < 10^9."""
        while True:
            if m <= log10(10**3) and m % 2:
                return 1, 9
            elif m <= log10(10**3) + 0.5:
                return int((m-1)/2), 9 * 2

        return 1, 9
    m, N = limit_by_odd_m(S)

    ans = 0
    tmp = sum(range(m, 10))
    while m >= max(m // 2, N):
        candidate = nth_digit_sum(tmp)
        if candidate <= S:
            ans += max(0, tmp * m // 2 + challenger)
            tmp += tmp  # Advance to bigger chunks
        else:
            tmp += tmp  # Advance to bigger chunks
    return ans % MOD

