# Function to find the Lowest Common Ancestor (LCA) of nodes u and v.
def lca(u, v):
    # If both u and v have been set as 0 to indicate they are not null,
    # then the LCA is the maximum of u and v (because if it is not equal,
    # it has to be one of them, either u or v).
    if not u and not v:
        return int(max(parent[u], parent[v]) + 1)
    # If either of them is 0, then the key node is the non-null one.
    elif not u or not v:
        return parent[not u]
    # If u > 1, then u is a parent, and the LCA of u and v is the LCA of v or 1.
    elif u > 1:
        return lca(v, u)
    # If v > 1, then v is a parent, and the LCA of v and u is the LCA of u or 1.
    elif v > 1:
        return lca(u, v)

# Function to perform the first type of query on a segment.
