    edges = [(i, j) for i in range(1, N+1) for j in range(i+1, N+1) if (i, j) not in edges and (j, i) not in edges]
    graph = construct_tree(nodes, edges)
    prime_freq = [0] * (N + 1)
    prime_freq[1] = 1  # The root node 1 contributes to one prime subtree
    visited = [False] * (N + 1)

