from typing import List
from heapq import heapify, heappop, heappush

def can_win_match(opponents: List[int], teammates: List[int]) -> str:
    if len(neutralize(opponents)) < len(teammates):
        return "YES\n" + neutralize(opponents)
    return "NO"

def neutralize(strengths: List[int]) -> List[int]:
    queue = [(-strength, i) for i, strength in enumerate(strengths)]
    heapify(queue)
    outcome, first = [], []
    while queue:
        score, i = heappop(queue)
        if first and abs(first[-1][0] - score) == 1:
            first.pop()  # Condition for a viable ordering
        if i == len(teammates) and first and outcome[-1][1] in [first[-1][1], 1]:
            continue
        while outcome and (outcome[-1][1] < score or outcome[-1][0] + 1 < -outcome[-1][1] + 1):
            heappop(outcome)
        outcome.append((score, first[-1][1] + 1))
        if i + 1 != len(teammates):
            heappush(queue, (-(strengths[i + 1], i + 1)))
    return outcome

def print_orderings(outcome: List[List[int]]) -> None:
    print("YES\n" + " ".join(map(str, [outcome[i][1] - 1 for i in range(len(outcome))])))

