from math import isqrt

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, isqrt(n) + 1, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False
    return True

def generate_subtrees(N, values):
    children = [[] for _ in range(N)]
    for i in range(1, N):
        children[values[i-1]].append(i)
    return children

def generate_edges(subtrees):
    edges = []
    for i in range(N):
        for j in subtrees[i]:
            if j != i:
                edges.append((i, j))
    return edges

def solve(N, values):
    subtrees = generate_subtrees(N, values)
    while not is_prime(sum(values)):
        # Try swapping two nodes to form a prime subtree
        i = None
        for j in range(N):
            if subtrees[j]:
                for k in range(len(subtrees[j]) - 1):
                    for l in range(k + 1, len(subtrees[j])):
                        temp = subtrees[j][l - 1]
                        subtrees[j][l - 1] = subtrees[j][l]
                        subtrees[j][l] = temp
                        # Recalculate if the subtrees form a prime subtree
                        if is_prime(sum(values)):
                            return generate_edges(subtrees)
                        subtrees[j] = []
                    subtrees[j] = []
    return generate_edges(subtrees)

