import sys

def build_tree(n):
    parent = [-1] * (n + 1)  # Initialize parent array and mark root node
    for i in range(2, n + 1):
        parent[i] = parent[i - 1]  # Parent is the index of parent in the graph
    return parent

def update_tree(parent, indices, updates):
    for node, update in zip(indices, updates):
        for i in range(node, 1, -1):
            if parent[i] != i:
                parent[i] = parent[parent[i]]
    return parent

