import sys

def longest_increasing_subsequence(b, t, maxb):
    dp = [1] * len(b)
    for i in range(len(b)):
        for j in range(i):
            if b[i] > b[j] and (b[i] + t * i) // (t * (i - j) + j) <= maxb:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def process_k_sequences(k, n, maxb, t):
    return [longest_increasing_subsequence(x, t, maxb) for x in sys.stdin.read().strip().split()]

