MOD = 998244353

def power(a, n):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * a) % MOD
        a = (a * a) % MOD
        n = n // 2
    return result

def get_element(a, n, mod):
    return power(a, n) % mod

def binomial_coefficients(n, k, mod):
    C = [[0] * (k+1) for _ in range(n)]
    C[0][0] = 1
    for i in range(n):
        for j in range(1, i + 1):
            C[i][j] += C[i - 1][j - 1]
            if j > 1:
                C[i][j] += (C[i - 1][j - 2] * 2) % mod
            C[i][j] %= mod
    return C[n-1][k]

def modulo_inverse(a, mod):
    return power(a, mod - 2)

def count_leaf_partitions(n, p):
    # Assuming p[i] is the i-th parent node
    p = [p[i] - 1 for i in range(1, n)]
    results = [1] * n

    def all_leaves_to_root(i, counter):
        left_subtree = right_subtree = 0
        for j in p:
            if j == -1:
                right_subtree += 1
            elif j == i:
                left_subtree += 1
            else:
                left_subtree += all_leaves_to_root(j, counter)
        counter[i] = left_subtree if left_subtree >= right_subtree else right_subtree + 1
        return counter[i]

    for i in range(1, n):
        all_leaves_to_root(i, results[:])

    factorials = [0] * (n + 1)
    factorials[1] = get_element(5, n, MOD)
    for i in range(2, n + 1):
        factorials[i] = (factorials[i - 1] * i) % MOD
    result = 0
    for i in range(n - 1, 0, -1):
        result = (result + (get_element(3, binomial_coefficients(n, i, MOD), MOD) * factorials[n - i]) % MOD * modulo_inverse(power(2, results[i], MOD), MOD)) % MOD
        results = [get_element(3, binomial_coefficients(n, i, MOD), MOD) * results[i - 1] % MOD] + results[:-1]
    return get_element(2, results, MOD)

