import sys

def can_reach_draw(N, ranks_A, ranks_B, S):
    if S == 1:
        # In the first subtask, ensure Chef and his friend can beat each other's cards in the first turn.
        if len(set(ranks_A) - set(ranks_B)) > 0 or len(set(ranks_B) - set(ranks_A)) > 0:
            return "NO"
        else:
            return "YES"
    else:
        # In the second subtask, calculate the necessary turns to ensure a draw.
        extra_ranks = [abs(n - m) for n in ranks_A for m in ranks_B if n != m]
        turns_needed = sum(extra_ranks)
        if S in [1, 3] and turns_needed % 2 == 0 or S in [2, 4] and turns_needed % 2 != 0:
            return "YES"
        else:
            return "NO"

def solve(input_lines):
    for line in input_lines:
        if line.startswith("T"):
            T, S = line.split(" ")[1].split(";")[1][0], line.split(" ")[2]
        else:
            input_lines = [line.split(";")[1]] * int(T)
            output = []
            for line in input_lines:
                ranks_A, ranks_B = [int(a) for a in line.split(" ")[1].split()], [int(b) for b in line.split(" ")[2].split()]
                result = can_reach_draw(len(ranks_A), ranks_A, ranks_B, int(S))
                output.append(result)
            sys.stdout.write("\n".join(output) + "\n")

if __name__ == "__main__":
    input_lines = []
    for line in sys.stdin:
        if line.startswith("T"):
            break
        input_lines.append(line.strip())
    solve(input_lines)
