from itertools import product

mod = 1000000007

def count_victories(N, M, K):
    # Limit the range of N, M, and K to 1000 for simplicity in comparison
    if N > 1000 or M > 1000 or K > 1000:
        return -1

    # Generate all possible initial decks combinations
    decks = [(i, j, k) for i, j, k in product(range(3), repeat=3) if 1 <= i <= N and 1 <= j <= M and 1 <= k <= K]

    def count_patterns(N, M, K, deck):
        # Calculate the number of patterns for the deck
        count = (27 if all([N, M, K]) else 0) + (3 * (2 ** min(N + M, min(K, 0)))).mod(mod)

        # Apply the coprimality condition for individual cases
        if (N + M + K) % 2 == 0:
            count /= 2

        if N % 2 == 0 and M % 2 == 0 and K % 2 == 0:
            count /= 6

        if N % 3 == 0 and M % 3 == 0 and K % 3 == 0:
            count /= 36
        elif N % 3 == 0 or M % 3 == 0 or K % 3 == 0:
            count *= 2

        return count.mod(mod)

    total_victories = 0
    for n, m, k in decks:
        total_victories += count_patterns(n, m, k, (0, n, 0, m, 0, k)) + (1 if (n in (1, 3) or m in (1, 3) or k in (1, 3)) else 0)

    return total_victories.mod(mod)

