MOD = 998244353

def inverse(a):
    return pow(a, MOD-2, MOD)

def partition_ways(n):
    graph = {i: [] for i in range(1, n+1)}

    edges = list(map(int, input().split()))
    for i in range(1, n):
        graph[edges[i-1]].append(edges[i])

    leaves = set()
    for i in range(1, n+1):
        if len(graph[i]) == 0:
            leaves.add(i)

    result = 1
    for i in range(1, n):
        leaves.add(i+1)
        graph[i+1] = [a for node in graph[i+1] if node in leaves ]

    for _ in range(n - 2):
        leaves = set(node for node in graph if len(graph[node]) == 0)
        result = sum(map(inverse, result * pow(len(leaves), 2, MOD))) % MOD

    return result

n = int(input().strip())
print(partition_ways(n))
